namespace VideoBlackout.Wpf;

/// <summary>Translations for the website locales. Missing keys fall back to English.</summary>
public static class LocalePacks
{
    public static bool TryGet(string code, string key, out string text)
    {
        if (Pack(code).TryGetValue(key, out var found) && !string.IsNullOrEmpty(found))
        {
            text = found;
            return true;
        }
        text = "";
        return false;
    }

    private static Dictionary<string, string> Pack(string code) => code switch
    {
        "zh-CN" => Zh,
        "zh-TW" => Tw,
        "de" => De,
        "fr" => Fr,
        "es" => Es,
        "pt-BR" => Pt,
        "ja" => Ja,
        _ => Empty
    };

    private static readonly Dictionary<string, string> Empty = new();

